begin;

create table if not exists public.service_variant_prices (
 id bigint generated by default as identity primary key,
 created_at timestamptz not null default now(),
 clinic_id bigint not null references public.clinics(id) on delete restrict,
 branch_id bigint not null references public.branches(id) on delete restrict,
 service_variant_id bigint not null references public.service_variants(id) on delete cascade,
 staff_id bigint not null references public.staff(id) on delete cascade,
 price numeric(12,2) not null check(price >= 0),
 is_starting_from boolean not null default false,
 is_active boolean not null default true,
 unique(service_variant_id, staff_id)
);

alter table public.service_variant_prices enable row level security;
drop policy if exists "Clinic users manage doctor variant prices" on public.service_variant_prices;
create policy "Clinic users manage doctor variant prices" on public.service_variant_prices for all to authenticated
using(exists(select 1 from public.user_clinic_access a where a.user_id=auth.uid() and a.clinic_id=service_variant_prices.clinic_id and (a.branch_id is null or a.branch_id=service_variant_prices.branch_id)))
with check(exists(select 1 from public.user_clinic_access a where a.user_id=auth.uid() and a.clinic_id=service_variant_prices.clinic_id and (a.branch_id is null or a.branch_id=service_variant_prices.branch_id)));

do $$
declare v_clinic_id bigint; v_branch_id bigint; v_staff_id bigint;
begin
 select id into v_clinic_id from public.clinics where code='PANTHERA' limit 1;
 select id into v_branch_id from public.branches where clinic_id=v_clinic_id and code='MAIN' limit 1;
 select id into v_staff_id from public.staff where clinic_id=v_clinic_id and lower(trim(staff_name))='dr fatima khaled' and is_active=true limit 1;
 if v_clinic_id is null or v_branch_id is null or v_staff_id is null then raise exception 'Panthera clinic, MAIN branch, or Dr Fatima Khaled was not found'; end if;

 -- Preserve the existing price list for Dr Fatima Alsatouf and Dr Maram before adding the separate Dr Fatima Khaled prices.
 insert into public.service_variant_prices(clinic_id,branch_id,service_variant_id,staff_id,price,is_starting_from,is_active)
 select v_clinic_id,v_branch_id,sv.id,st.id,sv.price,sv.is_starting_from,true
 from public.service_variants sv
 join public.staff_services ss on ss.service_id=sv.service_id and ss.is_active
 join public.staff st on st.id=ss.staff_id and st.clinic_id=v_clinic_id
 where sv.clinic_id=v_clinic_id and sv.is_active and lower(trim(st.staff_name)) in('dr fatima alsatouf','dr maram')
 on conflict(service_variant_id,staff_id) do nothing;

 create temporary table zernio_khaled_import(code text,name text,price numeric,starting boolean) on commit drop;
 insert into zernio_khaled_import select code,name,price,starting from jsonb_to_recordset('[{"code":"CONSULTATION","name":"CONSULTATION DERMATOLOGIST RESIDENT","price":200,"starting":false},{"code":"CONSULTATION","name":"CONSULTATION CONSULTANT","price":200,"starting":false},{"code":"CONSULTATION","name":"CONSULTATION SPECIALIST","price":200,"starting":false},{"code":"PICOWAY-LASER","name":"LIPS WHITENING","price":699,"starting":false},{"code":"PICOWAY-LASER","name":"HYPERPIGMENTATION LARGE AREA","price":1000,"starting":true},{"code":"PICOWAY-LASER","name":"HYPERPIGMENTATION SMALL AREA","price":699,"starting":true},{"code":"PICOWAY-LASER","name":"TATTOO REMOVAL LARGE AREA","price":1000,"starting":true},{"code":"PICOWAY-LASER","name":"TATTOO REMOVAL SMALL AREA","price":699,"starting":true},{"code":"FILLER","name":"2ML RADIESSE","price":1998,"starting":false},{"code":"FILLER","name":"1ML JUVEDERM VOLUMA","price":999,"starting":false},{"code":"FILLER","name":"1ML TEOSYAL RHA2","price":999,"starting":false},{"code":"FILLER","name":"1ML TEOSYAL ULTRA DEEP","price":999,"starting":false},{"code":"FILLER","name":"1ML BELOTERO","price":999,"starting":false},{"code":"FILLER","name":"1ML RESTYLANE KYSS","price":999,"starting":false},{"code":"FILLER","name":"HAYALORONIDASE","price":1000,"starting":false},{"code":"FILLER","name":"BODY FILLER HAYACORP 10ML","price":2800,"starting":false},{"code":"FILLER","name":"CAL HYBRID FILLER","price":999,"starting":false},{"code":"FILLER","name":"1ML RADIESSE","price":999,"starting":false},{"code":"FILLER","name":"1ML FILLER","price":999,"starting":false},{"code":"FILLER","name":"1ML STYLAGE M","price":999,"starting":false},{"code":"FILLER","name":"1ML EPTQ","price":999,"starting":false},{"code":"FILLER","name":"1ML TEOSYAL REDENISTY 2","price":999,"starting":false},{"code":"FILLER","name":"1ML DERMA STYLE","price":699,"starting":false},{"code":"FILLER","name":"1ML JUVEDERM ULTRA DEEP4","price":999,"starting":false},{"code":"LIPS-FILLER","name":"1ML TEOSYAL RHA3","price":999,"starting":false},{"code":"LIPS-FILLER","name":"1 ML TEOYSYAL RH2","price":999,"starting":false},{"code":"LIPS-FILLER","name":"1ML STYLAGE M","price":999,"starting":false},{"code":"LIPS-FILLER","name":"1ML DERMA STYLE SMILE","price":699,"starting":false},{"code":"LIPS-FILLER","name":"1ML RESTYLANE KYSS","price":999,"starting":false},{"code":"BOTOX","name":"MESO BOTOX ALLERGAN","price":699,"starting":false},{"code":"BOTOX","name":"MESO BOTOX DYSPORT","price":699,"starting":false},{"code":"BOTOX","name":"BOTOX GUMMY SMILE ALLERGAN","price":499,"starting":false},{"code":"BOTOX","name":"BOTOX GUMMY SMILE DYSPORT","price":499,"starting":false},{"code":"BOTOX","name":"BOTOX MASSETER MUSCLE ALLERGAN","price":699,"starting":false},{"code":"BOTOX","name":"BOTOX MASSETER MUSCLE DYSPORT","price":699,"starting":false},{"code":"BOTOX","name":"BOTOX FOREHEAD ALLERGAN","price":699,"starting":false},{"code":"BOTOX","name":"BOTOX FOREHEAD DYSPORT","price":699,"starting":false},{"code":"BOTOX","name":"BOTOX HYPERHYDROSIS ALLERGAN","price":1499,"starting":false},{"code":"BOTOX","name":"BOTOX HYPERHYDROSIS DYSPORT","price":1499,"starting":false},{"code":"BOTOX","name":"1ML BOTOX ALLERGAN","price":699,"starting":false},{"code":"BOTOX","name":"1ML BOTOX DYSPORT","price":699,"starting":false},{"code":"BOTOX","name":"1.5ML BOTOX ALLERGAN","price":1200,"starting":false},{"code":"BOTOX","name":"1.5ML BOTOX DYSPORT","price":1200,"starting":false},{"code":"BOTOX","name":"BOTOX FACE & NECK ALLERGAN","price":1499,"starting":false},{"code":"BOTOX","name":"BOTOX FACE & NECK DYSPORT","price":1499,"starting":false},{"code":"BOTOX","name":"BOTOX LARGE AREA ALLERGAN","price":1999,"starting":false},{"code":"BOTOX","name":"BOTOX LARGE AREA DYSPORT","price":1200,"starting":false},{"code":"BOTOX","name":"BOTOX SMALL AREA DYSPORT","price":499,"starting":false},{"code":"BOTOX","name":"1.5ML BOTOX XIOMEN","price":1200,"starting":false},{"code":"BOTOX","name":"1ML BOTOX XIOMEN","price":699,"starting":false},{"code":"BOTOX","name":"BOTOX SMALL AREA ALLERGAN","price":499,"starting":false},{"code":"BOTOX","name":"BARBIE BOTOX DYSPORT","price":1999,"starting":false},{"code":"BOTOX","name":"BARBIE BOTOX ALLERGAN","price":1999,"starting":false},{"code":"SKIN-BOOSTER","name":"DIVES","price":1400,"starting":false},{"code":"SKIN-BOOSTER","name":"JALUPRO SUPER HYDRO","price":1400,"starting":false},{"code":"SKIN-BOOSTER","name":"JALUPRO HMW","price":1400,"starting":false},{"code":"SKIN-BOOSTER","name":"EXOBAZ","price":1200,"starting":false},{"code":"SKIN-BOOSTER","name":"PLASMA MAGELLAN","price":2200,"starting":false},{"code":"SKIN-BOOSTER","name":"PLASMA PLUS","price":999,"starting":false},{"code":"SKIN-BOOSTER","name":"INNOVYAL","price":1200,"starting":false},{"code":"SKIN-BOOSTER","name":"DERMAPEN","price":500,"starting":false},{"code":"SKIN-BOOSTER","name":"DERMAPEN WITH MESO","price":1500,"starting":false},{"code":"SKIN-BOOSTER","name":"TRANXAMIC ACID","price":999,"starting":false},{"code":"SKIN-BOOSTER","name":"MESO","price":999,"starting":false},{"code":"SKIN-BOOSTER","name":"EXOSOME","price":999,"starting":false},{"code":"SKIN-BOOSTER","name":"SALMON","price":1200,"starting":false},{"code":"SKIN-BOOSTER","name":"HYDRO DELUXE","price":1700,"starting":false},{"code":"SKIN-BOOSTER","name":"PDRN","price":1200,"starting":false},{"code":"SKIN-BOOSTER","name":"PROFHILO","price":1200,"starting":false},{"code":"SKIN-BOOSTER","name":"JALUPRO CLASSIC","price":1400,"starting":false},{"code":"PEELING","name":"M.A.D PEELING","price":999,"starting":false},{"code":"PEELING","name":"CIMEL","price":999,"starting":false},{"code":"POLYLACTIC-ACID","name":"5ML SCULPTRA","price":2000,"starting":false},{"code":"POLYLACTIC-ACID","name":"STICOL VOLUME","price":3500,"starting":false},{"code":"POLYLACTIC-ACID","name":"10ML SCULPTRA","price":3500,"starting":false},{"code":"HAIR-THERAPY","name":"ACELL","price":5000,"starting":false},{"code":"HAIR-THERAPY","name":"ALPACIA SMALL AREA","price":500,"starting":false},{"code":"HAIR-THERAPY","name":"PLASMA PLUS","price":999,"starting":false},{"code":"HAIR-THERAPY","name":"PLASMA MAGELLAN","price":2500,"starting":false},{"code":"HAIR-THERAPY","name":"EXOSOME 1ML","price":999,"starting":false},{"code":"HAIR-THERAPY","name":"MESO HAIR 1ML","price":999,"starting":false},{"code":"HAIR-THERAPY","name":"MINOXIDIL 1ML","price":999,"starting":false},{"code":"HAIR-THERAPY","name":"DUTASTERIDE 1ML","price":999,"starting":false},{"code":"FRAXIS","name":"FRAXIS DUO","price":1500,"starting":false},{"code":"FRAXIS","name":"FRACTIONAL","price":1000,"starting":false},{"code":"FRAXIS","name":"MICRONEEDLING","price":1000,"starting":false},{"code":"FRAXIS","name":"SURGICAL LASER","price":500,"starting":true},{"code":"FRAXIS","name":"WART REMOVSAL","price":500,"starting":true},{"code":"FRAXIS","name":"SKIN TAG REMOVAL","price":500,"starting":true}]'::jsonb)
 as x(code text,name text,price numeric,starting boolean);

 -- Materials/options are shared by service name, while their prices are doctor-specific.
 insert into public.service_variants(clinic_id,service_id,name,price,is_starting_from,is_active)
 select distinct on(s.id,lower(i.name)) v_clinic_id,s.id,i.name,i.price,i.starting,true
 from zernio_khaled_import i join public.services s on s.clinic_id=v_clinic_id and s.code=i.code
 order by s.id,lower(i.name),i.name
 on conflict(service_id,lower(name)) do update set is_active=true;

 delete from public.staff_services where staff_id=v_staff_id;
 insert into public.staff_services(staff_id,service_id,is_active,duration_minutes)
 select v_staff_id,s.id,true,s.duration_minutes from public.services s
 where s.clinic_id=v_clinic_id and s.code in('CONSULTATION','PICOWAY-LASER','FILLER','LIPS-FILLER','BOTOX','SKIN-BOOSTER','PEELING','POLYLACTIC-ACID','HAIR-THERAPY','FRAXIS')
 on conflict(staff_id,service_id) do update set is_active=true,duration_minutes=excluded.duration_minutes;

 insert into public.service_variant_prices(clinic_id,branch_id,service_variant_id,staff_id,price,is_starting_from,is_active)
 select v_clinic_id,v_branch_id,sv.id,v_staff_id,i.price,i.starting,true
 from zernio_khaled_import i
 join public.services s on s.clinic_id=v_clinic_id and s.code=i.code
 join public.service_variants sv on sv.service_id=s.id and lower(sv.name)=lower(i.name)
 on conflict(service_variant_id,staff_id) do update set price=excluded.price,is_starting_from=excluded.is_starting_from,is_active=true;

 update public.service_variant_prices p set is_active=false
 where p.staff_id=v_staff_id and not exists(
  select 1 from zernio_khaled_import i join public.services s on s.clinic_id=v_clinic_id and s.code=i.code
  join public.service_variants sv on sv.service_id=s.id and lower(sv.name)=lower(i.name)
  where sv.id=p.service_variant_id
 );
end $$;

select 'doctor_services' check_name,count(*) row_count from public.staff_services ss join public.staff st on st.id=ss.staff_id
where lower(trim(st.staff_name))='dr fatima khaled' and ss.is_active
union all
select 'doctor_variant_prices',count(*) from public.service_variant_prices p join public.staff st on st.id=p.staff_id
where lower(trim(st.staff_name))='dr fatima khaled' and p.is_active
union all
select 'doctor_starting_from_prices',count(*) from public.service_variant_prices p join public.staff st on st.id=p.staff_id
where lower(trim(st.staff_name))='dr fatima khaled' and p.is_active and p.is_starting_from
union all
select 'other_doctors_preserved_prices',count(*) from public.service_variant_prices p join public.staff st on st.id=p.staff_id
where lower(trim(st.staff_name)) in('dr fatima alsatouf','dr maram') and p.is_active;

commit;
